const tabId = 1148881640;

const pageData = await browserjs(tabId, () => {
  // Let's get headings, card titles, descriptions, buttons/links
  const headings = Array.from(document.querySelectorAll("h1, h2, h3, h4, h5")).map(h => ({
    tag: h.tagName,
    text: h.textContent.trim()
  })).filter(h => h.text.length > 0);

