  const cards = Array.from(document.querySelectorAll(".card, [data-component-name*='card'], .credit-card, [class*='credit-card'], [class*='card-item'], [class*='cardContainer'], section, article")).map(el => ({
    className: el.className,
    text: el.innerText.trim().slice(0, 300)
  })).filter(c => c.text.toLowerCase().includes("card") || c.text.toLowerCase().includes("bonvoy"));

  return {
    title: document.title,
    url: window.location.href,
    headings,
    cardsCount: cards.length,
    bodySnippet: document.body.innerText.slice(0, 3000)
  };
});

console.log("URL:", pageData.url);
console.log("Title:", pageData.title);
console.log("Headings:", JSON.stringify(pageData.headings, null, 2));
console.log("Body snippet:\n", pageData.bodySnippet.slice(0, 2000));

