const tabId = 1148881640;

const details = await browserjs(tabId, () => {
  // Let's find sections describing each card
  const cardNames = [
    "Marriott Bonvoy Boundless® Credit Card from Chase",
    "Marriott Bonvoy Bold® Credit Card from Chase",
    "Marriott Bonvoy Bevy® American Express® Card",
    "Marriott Bonvoy Brilliant® American Express® Card",
    "Marriott Bonvoy Business® American Express® Card"
  ];

  // Let's get the full text around each card or the card containers
  const containers = Array.from(document.querySelectorAll("div, section, article")).filter(el => {
    return cardNames.some(name => el.textContent.includes(name));
  });

  // Let's extract structured info by card
  const results = {};

  // Let's also check FAQ answers
  const faqs = Array.from(document.querySelectorAll("h2, h3")).filter(h => h.textContent.includes("?")).map(h => {
    let next = h.nextElementSibling;
    let answer = "";
    while (next && !["H1", "H2", "H3"].includes(next.tagName)) {
      answer += next.innerText + "\n";
      next = next.nextElementSibling;
    }
    return { question: h.textContent.trim(), answer: answer.trim() };
  });

  return {
    pageText: document.body.innerText,
    faqs
  };
});

// Let's search pageText for each card and extract sections
const fullText = details.pageText;

console.log("Full text length:", fullText.length);
// Write full text to a temp file so we can inspect or search it
await write("tmp://marriott_cards_text.txt", fullText);

console.log("FAQs count:", details.faqs.length);
for (const f of details.faqs) {
  console.log("Q:", f.question);
  console.log("A:", f.answer.slice(0, 300));
}

